 BogMatch m;bool had,restored;string saved,folder;int errors,races;bool paused;readonly bool[] submerged=new bool[4],refilled=new bool[4],finished=new bool[4];readonly float[] minimum={14,14,14,14},prior={14,14,14,14};readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("BogEvidence");yield return SportsProbeScene.Ensure<BogMatch>("TruckBogSnorkelling");m=FindAnyObjectByType<BogMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);m.weather=1;var scoreTally=new SportsScoreAcceptance.Tally(m);bool awardCaptured=false,captionsMatch=true;Check(m.StartMatch(),"four AI flooded-trench race series starts without controllers");Time.timeScale=4;float end=Time.realtimeSinceStartup+900,next=0;int last=0;while(!m.Finished&&Time.realtimeSinceStartup<end){captionsMatch&=m.Header.EndsWith(" | "+m.course.weather.Description,StringComparison.Ordinal);if(!awardCaptured&&m.ScoreJournal.Count>0){awardCaptured=true;yield return SportsScoreAcceptance.CaptureAward(m,Check,folder+"/placement-award");}for(int i=0;i<4;i++){var r=m.racers[i];submerged[i]|=r.Submerged&&r.Air<13;refilled[i]|=r.IntakeOpen&&r.Air>prior[i]+.005f;minimum[i]=Mathf.Min(minimum[i],r.Air);prior[i]=r.Air;finished[i]|=r.State==BogState.Finished;}if(!paused&&Array.Exists(m.racers,r=>r.Submerged&&r.State==BogState.Racing)){paused=true;m.Pause();var p=m.racers[0].truck.body.position;float air=m.racers[0].Air,clock=m.Clock;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&p==m.racers[0].truck.body.position&&air==m.racers[0].Air&&clock==m.Clock,"pause preserves actual submerged body air and race clock");m.Resume();Time.timeScale=4;}if(m.Phase==BogPhase.RaceResult&&m.series.completed!=last){last=m.series.completed;races++;log.AppendLine("RACE "+m.series.round+" ranks="+string.Join(",",m.series.ranks)+" points="+string.Join(",",m.series.total)+" recoveries="+string.Join(",",Array.ConvertAll(m.racers,r=>r.Recoveries)));}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE round="+m.series.round+" phase="+m.Phase+" clock="+m.Clock+" racers="+string.Join(" | ",Array.ConvertAll(m.racers,r=>r.State+" z="+r.truck.body.position.z.ToString("F1")+" y="+r.truck.body.position.y.ToString("F1")+" air="+r.Air.ToString("F1")+" flags="+r.Checkpoint+" recoveries="+r.Recoveries))+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}Check(captionsMatch&&m.Header.EndsWith(" | "+m.course.weather.Description,StringComparison.Ordinal),"header follows actual installed forecast throughout all physical races");scoreTally.Verify(slot=>m.series.total[slot],Check);scoreTally.Dispose();if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,m.ResultPlace,slot=>(double?)m.series.total[slot],slot=>m.series.winner==slot);
 Check(m.Finished&&m.series.winner>=0&&races>=3,"complete actual three-race series and real tiebreak if needed");for(int i=0;i<4;i++){Check(submerged[i]&&refilled[i],"actual intake submersion drains and legal surfacing refills racer="+i+" minimum="+minimum[i]);Check(finished[i],"racer physically finishes at least once through ordered gates slot="+i);}Check(m.series.total[m.series.winner]>0,"winner has genuine placement points, not all-DNF invented result");Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Exclude).Length==1,"one split-screen listener");log.AppendLine("ERRORS="+errors+". Native NWH/PhysX buoyancy/drag/air/dive race series; no hardware/human playtest or frame-rate benchmark.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("BOG_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
